import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Page } from '@playwright/test';
import { test, expect } from './fixtures';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

test.describe('Fluxo Principal da Extensão - Dashboard & Componentes', () => {
    test.beforeEach(async ({ page, extensionId }) => {
        // Navigates to the build entrypoint path generated by Vite inside dist/
        await page.goto(`chrome-extension://${extensionId}/src/index.html`);
    });

    test('deve renderizar a Dashboard com a Navbar e carregar o módulo AFD por padrão', async ({ page }) => {
        // Valida título da aplicação na Sidebar
        const logoTitle = page.locator('.bga-navbar__titulo');
        await expect(logoTitle).toHaveText('Buscador Global');

        // Valida que o container principal de layout está presente
        const dashboardLayout = page.locator('.bga-dashboard-layout');
        await expect(dashboardLayout).toBeVisible();

        // Valida que a view padrão "Funcionários (Tipo 5)" foi montada na área de conteúdo
        const mainContent = page.locator('.bga-dashboard-content');
        await expect(mainContent).toBeVisible();
        await expect(page.getByTestId('view-afd-funcionarios')).toBeVisible();
    });
    test('deve alternar entre os grupos da Navbar mantendo o isolamento de visualização', async ({ page }) => {
        // Expande o grupo "Coletor"
        const coletorGroupHeader = page.getByRole('button', { name: /coletor/i });
        await expect(coletorGroupHeader).toBeVisible();
        await coletorGroupHeader.click();

        // Clica no subitem "Matrícula"
        const matriculaSubItem = page.getByText('Matrícula');
        await expect(matriculaSubItem).toBeVisible();
        await matriculaSubItem.click();

        // Garante que o conteúdo foi atualizado para a View selecionada
        await expect(page.getByTestId('view-coletor-matricula')).toBeVisible();
        await expect(page.getByTestId('view-afd-funcionarios')).toHaveCount(0);
    });

    test('não deve exibir o Show Case no build de produção, mantendo o Coletor', async ({ page }) => {
        await expect(page.getByRole('button', { name: /coletor/i })).toBeVisible();
        await expect(page.getByRole('button', { name: /show case/i })).toHaveCount(0);
    });
});
test.describe('Leitura do AFD pelo worker', () => {
    const fixture = (nome: string) => path.resolve(__dirname, '../src/afd/__fixtures__', nome);
    // A view ativa também tem role="status" ("Lendo o arquivo AFD…"); o resumo é o da área de upload.
    const statusDoUpload = (page: Page) =>
        page.getByRole('region', { name: 'Arquivo Fonte de Dados (AFD)' }).getByRole('status');

    test.beforeEach(async ({ page, extensionId }) => {
        await page.goto(`chrome-extension://${extensionId}/src/index.html`);
    });

    test('deve ler um AFD da Portaria 671 e mostrar o resumo', async ({ page }) => {
        await page.getByLabel('Selecionar arquivo').setInputFiles(fixture('afd-671.txt'));

        await expect(page.getByText('afd-671.txt')).toBeVisible();
        await expect(statusDoUpload(page)).toContainText(/Portaria 671 · \d+ linhas lidas/);
        await expect(page.getByRole('progressbar')).toHaveCount(0);
    });

    test('deve manter o resultado do último arquivo ao trocar no meio da leitura', async ({ page }) => {
        const campo = page.getByLabel('Selecionar arquivo');

        await campo.setInputFiles(fixture('afd-671.txt'));
        await campo.setInputFiles(fixture('afd-595.txt'));

        await expect(statusDoUpload(page)).toContainText('Portaria 595');
        await expect(page.getByText('afd-595.txt')).toBeVisible();
    });
});
